import{_ as t,o as a,c as s,a5 as n}from"./chunks/framework.bIR-4glx.js";const k=JSON.parse('{"title":"Toolkit Walkthrough: Let AI Continue a 90-Day Learning Project across Sessions","description":"Use an explicitly synthetic Python-learning case to show how Learning State, an AI Task Brief, an unaided baseline, an artifact, an Evidence Chain, Weekly Review, and a Reader Field Note hand work over.","frontmatter":{"title":"Toolkit Walkthrough: Let AI Continue a 90-Day Learning Project across Sessions","description":"Use an explicitly synthetic Python-learning case to show how Learning State, an AI Task Brief, an unaided baseline, an artifact, an Evidence Chain, Weekly Review, and a Reader Field Note hand work over.","updated":"2026-09-02T00:00:00.000Z"},"headers":[],"relativePath":"en/templates/toolkit-walkthrough.md","filePath":"en/templates/toolkit-walkthrough.md","lastUpdated":1788307200000}'),i={name:"en/templates/toolkit-walkthrough.md"};function o(r,e,l,d,h,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="toolkit-walkthrough-let-ai-continue-a-90-day-learning-project-across-sessions" tabindex="-1">Toolkit Walkthrough: Let AI Continue a 90-Day Learning Project across Sessions <a class="header-anchor" href="#toolkit-walkthrough-let-ai-continue-a-90-day-learning-project-across-sessions" aria-label="Permalink to &quot;Toolkit Walkthrough: Let AI Continue a 90-Day Learning Project across Sessions&quot;">​</a></h1><p>Many readers do not lack plans. They do not know when each worksheet should open. Another common problem appears during a three-month learning project: one AI conversation grows too long, while a new conversation seems to erase the state that came before it.</p><p>The answer is not to demand permanent memory from AI. <strong>Let a file preserve state and let AI handle the current task.</strong></p><p>This page uses a Python learner preparing for a career change as a complete walkthrough. The person, tasks, code results, scores, and feedback are synthetic. They demonstrate how to fill the tools; they are not a real reader outcome and do not prove that ninety days is enough for a career transition.</p><h2 id="this-is-not-a-success-story" tabindex="-1">This Is Not a Success Story <a class="header-anchor" href="#this-is-not-a-success-story" aria-label="Permalink to &quot;This Is Not a Success Story&quot;">​</a></h2><p>The demonstration learner has these conditions:</p><ul><li>Can read variables, conditions, and simple loops but cannot independently complete a small program;</li><li>Can reliably invest four 45-minute sessions each week;</li><li>Has a ninety-day goal of independently completing a command-line tool that reads CSV, validates rows, and prints a summary;</li><li>Will not upload company data, ask AI to write the final artifact, or repay interruption with lost sleep;</li><li>Will not add frameworks or another course if core code still cannot be explained on day fourteen.</li></ul><p>These conditions are demonstration boundaries. Your starting point, time, body, work, and goal may differ completely.</p><h2 id="scene-why-the-plan-loses-its-memory" tabindex="-1">Scene: Why the Plan Loses Its Memory <a class="header-anchor" href="#scene-why-the-plan-loses-its-memory" aria-label="Permalink to &quot;Scene: Why the Plan Loses Its Memory&quot;">​</a></h2><p>The initial failure is to leave everything inside one chat window:</p><ol><li>Ask AI for a twelve-week plan;</li><li>Ask questions, practise, and revise code in the same conversation every day;</li><li>Depend on prior messages to preserve errors, progress, and the next step;</li><li>As context grows, new answers begin mixing old tasks together;</li><li>After opening a new conversation, reconstruct the learner from a long recollection.</li></ol><p>Context length is not the only problem. A chat log has no stable version and does not clearly separate completed fact, AI interpretation, and next hypothesis. Learning state should not be trapped inside one provider or one conversation.</p><h2 id="the-job-of-each-of-five-tools" tabindex="-1">The Job of Each of Five Tools <a class="header-anchor" href="#the-job-of-each-of-five-tools" aria-label="Permalink to &quot;The Job of Each of Five Tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Job in this case</th><th>What it does not own</th></tr></thead><tbody><tr><td><a href="./learning-state">Learning State</a></td><td>Preserve cross-session facts, evidence, errors, boundaries, and next task</td><td>Every line of conversation</td></tr><tr><td><a href="./ai-task-brief">AI Task Brief</a></td><td>Bound the current 45-minute task, input, assistance, and acceptance</td><td>The whole life plan</td></tr><tr><td><a href="./evidence-chain">Evidence Chain</a></td><td>Compare unaided baseline, assisted version, delayed retest, and transfer</td><td>Proving “mastery” through one score</td></tr><tr><td><a href="./weekly-review">Weekly Review</a></td><td>Change one variable from one week&#39;s evidence</td><td>Turning one poor week into a verdict about character</td></tr><tr><td><a href="./reader-field-note">Reader Field Note</a></td><td>Record whether the toolkit entered action and where it remained unusable</td><td>Public disclosure or a rating of the book</td></tr></tbody></table><p>If this is your first use of the toolkit, follow this page for one week. Do not open every other template at the same time.</p><h2 id="step-one-put-state-outside-the-conversation" tabindex="-1">Step One: Put State outside the Conversation <a class="header-anchor" href="#step-one-put-state-outside-the-conversation" aria-label="Permalink to &quot;Step One: Put State outside the Conversation&quot;">​</a></h2><p>The learner creates <code>python-learning-state.md</code> instead of using an AI thread as memory:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Learning State — python-90d-v1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Updated: 2026-09-02</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Ninety-day situation: independently deliver a CSV-summary command-line tool and explain input validation, error handling, and tests.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Current baseline: can write variables, if, and for; cannot independently read CSV, separate functions, or write tests.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Reliable capacity: Monday, Wednesday, Friday, and Sunday, 45 minutes each.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Existing evidence: baseline/day-01.py; crashes on a row with an empty value.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Repeated errors: looking at answers first; treating running code as explained code; changing several variables and losing the cause.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Boundaries: synthetic data only; submit my version first; no make-up study after 23:00.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Current phase: days 1–14, calibrate.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Smallest next task: read a 12-row synthetic CSV, skip empty rows, and print valid-row count plus total amount.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Acceptance: the unaided version runs; I can explain each function; at least one failing test is preserved.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Stop condition: save state when 45 minutes ends; do not stay up to finish.</span></span></code></pre></div><p>The state file keeps only what can change the next action. Course notes, full chat logs, and every attempt belong in the evidence folder rather than on the state page.</p><h2 id="step-two-give-ai-one-task-at-a-time" tabindex="-1">Step Two: Give AI One Task at a Time <a class="header-anchor" href="#step-two-give-ai-one-task-at-a-time" aria-label="Permalink to &quot;Step Two: Give AI One Task at a Time&quot;">​</a></h2><p>A new conversation does not ask AI to “remember me”. It receives the latest state and one task brief:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Below is my Learning State file. First restate the version, goal, current evidence, main errors, boundaries, and next task in no more than six bullets. Point out conflicts or gaps. Do not add facts that are absent.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">This session has one task: read a synthetic CSV, skip empty rows, and print valid-row count plus total amount.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Process: let me submit an unaided version first; identify at most three problems that affect the result without giving full code; after I revise it, test with two cases. At 45 minutes, return five updates: completed, evidence, error/risk, handover, and next step.</span></span></code></pre></div><p>AI&#39;s first job is to restate the state, not begin a lecture. When the restatement is wrong, repair the state or prompt before generating another plan on a false premise.</p><h2 id="step-three-save-a-baseline-before-asking-for-help" tabindex="-1">Step Three: Save a Baseline before Asking for Help <a class="header-anchor" href="#step-three-save-a-baseline-before-asking-for-help" aria-label="Permalink to &quot;Step Three: Save a Baseline before Asking for Help&quot;">​</a></h2><p>The synthetic unaided attempt produces:</p><table tabindex="0"><thead><tr><th>Condition</th><th>Result</th><th>Evidence</th></tr></thead><tbody><tr><td>25 minutes, no answer</td><td>Reads valid rows; empty amount raises an exception; all logic in one function</td><td><code>evidence/week-01/baseline.py</code></td></tr><tr><td>AI identifies only three issues</td><td>Empty-value validation, function ownership, and missing tests become visible</td><td><code>evidence/week-01/feedback.md</code></td></tr><tr><td>After revision</td><td>Normal-row and empty-row tests pass; invalid amount format remains unsupported</td><td><code>evidence/week-01/revision.py</code></td></tr></tbody></table><p>The record is not “AI wrote the program”. It says the unaided version exposed three issues, AI helped classify them, the learner repaired two, and the third became the next task.</p><p>Asking for complete code first may produce a better-looking file while erasing the baseline and any way to tell which ability belongs to the learner.</p><h2 id="step-four-put-the-artifact-into-an-evidence-chain" tabindex="-1">Step Four: Put the Artifact into an Evidence Chain <a class="header-anchor" href="#step-four-put-the-artifact-into-an-evidence-chain" aria-label="Permalink to &quot;Step Four: Put the Artifact into an Evidence Chain&quot;">​</a></h2><p>Week one does not preserve the statement “learned CSV”. It records four time points:</p><table tabindex="0"><thead><tr><th>Time point</th><th>Condition</th><th>Synthetic result</th><th>What it still cannot show</th></tr></thead><tbody><tr><td>Baseline</td><td>No AI, 25 minutes</td><td>1/3 acceptance conditions pass</td><td>Understanding of error handling</td></tr><tr><td>Immediate after assistance</td><td>Three feedback points seen</td><td>2/3 pass; two functions can be explained</td><td>Retention after several days</td></tr><tr><td>Day-seven delayed retest</td><td>Old code closed; parallel CSV</td><td>2/3 pass; invalid amount is missed again</td><td>Adaptation to a new field</td></tr><tr><td>Transfer</td><td>Add a <code>currency</code> field</td><td>Finds where change belongs; currency validation incomplete</td><td>Structure begins to transfer, prerequisites remain missing</td></tr></tbody></table><p>The result is not perfect and is more informative than “maintained a seven-day streak”. The next variable is not pandas, a web framework, and a database. It is input validation and failing tests.</p><h2 id="step-five-continue-in-a-new-conversation" tabindex="-1">Step Five: Continue in a New Conversation <a class="header-anchor" href="#step-five-continue-in-a-new-conversation" aria-label="Permalink to &quot;Step Five: Continue in a New Conversation&quot;">​</a></h2><p>The weekly review writes only decision-changing information back into state:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Learning State — python-90d-v2</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Updated: 2026-09-08</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Completed: normal and empty CSV rows; logic separated into read_rows and summarize.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Evidence: week-01/baseline.py; revision.py; day-07-retest.py; tests.md.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Delayed result: 2/3 conditions remain on day seven; invalid amount fails again.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Main error: failure paths lack tests; normal output causes testing to stop too early.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Boundaries retained: synthetic data; unaided answer first; stop at 45 minutes; no repayment of missed time.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Smallest next task: write three failing tests before implementing parse_amount.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Acceptance: empty, alphabetic, and negative inputs have explicit outcomes; design choice can be explained aloud.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Next review: 2026-09-15.</span></span></code></pre></div><p>The old conversation can close. The new one needs only <code>v2</code> and the relevant evidence locations, not tens of thousands of words from the chat. <strong>AI did not track learning across sessions. The state file tracked it, and AI read and served that state.</strong></p><h2 id="step-six-complete-a-reader-field-note-after-seven-days" tabindex="-1">Step Six: Complete a Reader Field Note after Seven Days <a class="header-anchor" href="#step-six-complete-a-reader-field-note-after-seven-days" aria-label="Permalink to &quot;Step Six: Complete a Reader Field Note after Seven Days&quot;">​</a></h2><p>The synthetic demonstration must also inspect whether the toolkit supported action:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Entry problem: I did not know how a new AI conversation could continue a three-month plan.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Action: created a versioned Learning State, completed one CSV task, and saved an unaided version plus retest.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What remained after seven days: could write state v2 without the old chat and begin one defined task in a new conversation.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Failed transfer: knew errors should be preserved but still did not know how to classify them.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Most useful: the five-tool responsibility table and filled state example.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Still abstract: phase gates need examples for more kinds of goals.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Cannot conclude: this workflow guarantees job readiness after ninety days.</span></span></code></pre></div><p>The note remains private first. Only after paths, identity, and sensitive details are removed should a public version be considered.</p><h2 id="if-the-week-is-interrupted" tabindex="-1">If the Week Is Interrupted <a class="header-anchor" href="#if-the-week-is-interrupted" aria-label="Permalink to &quot;If the Week Is Interrupted&quot;">​</a></h2><p>The state file does not require repayment of the whole plan. The first return record states facts:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Interruption fact: no practice for seven days.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Cause evidence: two overtime evenings, one period of illness, no retest completed.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What I will not do: compress four lessons into the weekend or repay them through lost sleep.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Return action: run the previous tests, write one failing case, and update state.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">24-hour acceptance: preserve the failing test and the next 25-minute entry point.</span></span></code></pre></div><p>When health, safety, work responsibility, or relationships need priority, recovery itself can be the week&#39;s result. The plan serves life; life does not owe the plan an apology.</p><h2 id="session-protocol-you-can-copy" tabindex="-1">Session Protocol You Can Copy <a class="header-anchor" href="#session-protocol-you-can-copy" aria-label="Permalink to &quot;Session Protocol You Can Copy&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Restate the submitted state version, goal, evidence, errors, boundaries, and next task.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Identify conflicts and missing information; do not infer unwritten history.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Handle one minimum task only and let me submit the unaided version first.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">4.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Give at most three high-impact feedback points, separating observation, interpretation, and suggestion.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">5.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do not provide a complete answer unless I explicitly request it.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">6.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> End with: completed, evidence, error/risk, handover, and next step.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">7.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Treat the file as the source of truth and do not claim memory of other conversations.</span></span></code></pre></div><p>This protocol cannot guarantee that AI never errs. It makes errors easier to detect and preserves the learner&#39;s ownership of the problem, state, and final judgment.</p><h2 id="what-this-walkthrough-shows-and-does-not-show" tabindex="-1">What This Walkthrough Shows and Does Not Show <a class="header-anchor" href="#what-this-walkthrough-shows-and-does-not-show" aria-label="Permalink to &quot;What This Walkthrough Shows and Does Not Show&quot;">​</a></h2><p>It shows that five tools can form a clear handover: state lives outside the conversation, the task becomes smaller, unaided and assisted versions remain separate, a delayed retest occurs, and a new conversation has a reliable entry.</p><p>It does not show that:</p><ul><li>The synthetic learner will persist for ninety days;</li><li>This task difficulty fits every beginner;</li><li>AI always makes learning faster than studying without it;</li><li>Completing a command-line tool equals real job readiness;</li><li>One week represents long-term transfer.</li></ul><p>In real use, preserve your own baseline, artifacts, time, cost, and failures. The example shows how to fill the records. Reality decides whether they are useful.</p><h2 id="closing-give-memory-to-the-file-and-keep-judgment-with-yourself" tabindex="-1">Closing: Give Memory to the File and Keep Judgment with Yourself <a class="header-anchor" href="#closing-give-memory-to-the-file-and-keep-judgment-with-yourself" aria-label="Permalink to &quot;Closing: Give Memory to the File and Keep Judgment with Yourself&quot;">​</a></h2><p>A long learning project should not lose its past when a chat closes, and it should not impersonate continuity merely because one chat is long.</p><p>Let the state file remember what happened. Let evidence preserve what you actually made. Let the next conversation carry only the next step. Tools may change, models may update, and the plan may shrink. As long as you know where you came from, what remains unproved, and where the next task lives, learning is not trapped inside any conversation.</p><p>Related entry points: <a href="./learning-state">Learning State</a> | <a href="./ai-task-brief">AI Task Brief</a> | <a href="./evidence-chain">Evidence Chain</a> | <a href="./reader-field-note">Reader Field Note</a></p>`,56)])])}const u=t(i,[["render",o]]);export{k as __pageData,u as default};
